import { ADMIN_ROLES, type Role } from "@/lib/constants";
import { db } from "@/lib/db";

export const UPLOAD_KINDS = ["avatar", "cover", "post_image", "video", "doc"] as const;
export type UploadKind = (typeof UPLOAD_KINDS)[number];

export const UPLOAD_VISIBILITY: Record<UploadKind, string> = {
  avatar: "public",
  cover: "public",
  post_image: "public",
  video: "public",
  doc: "private",
};

export function isUploadKind(value: string): value is UploadKind {
  return (UPLOAD_KINDS as readonly string[]).includes(value);
}

/** Storage keys are generated by us: `<kind>/<year>/<month>/<20 hex>.<ext>`. */
export function isStorageKeyForKind(key: string, kind: UploadKind): boolean {
  return new RegExp(`^${kind}/\\d{4}/\\d{2}/[a-f0-9]{20}\\.[a-z0-9]+$`).test(key);
}

/**
 * Persists an uploaded object as a Media row and wires avatar/cover pointers.
 * Shared by the classic multipart route and the direct-to-R2 presigned flow.
 */
export async function finalizeUpload(params: {
  userId: string;
  role: Role;
  kind: UploadKind;
  storageKey: string;
  mimeType: string;
  sizeBytes: number;
}) {
  const media = await db.media.create({
    data: {
      ownerId: params.userId,
      kind: params.kind,
      storageKey: params.storageKey,
      mimeType: params.mimeType,
      sizeBytes: params.sizeBytes,
      visibility: UPLOAD_VISIBILITY[params.kind],
    },
  });

  if (params.kind === "avatar") {
    await db.user.update({ where: { id: params.userId }, data: { avatarKey: media.id } });
  }

  if (
    params.kind === "cover" &&
    (params.role === "teacher" || ADMIN_ROLES.includes(params.role))
  ) {
    const profile = await db.teacherProfile.findUnique({ where: { userId: params.userId } });
    if (profile) {
      await db.teacherProfile.update({
        where: { id: profile.id },
        data: { coverKey: media.id },
      });
    }
  }

  return media;
}
